{"tool":"calculate","code":"# Survey: licenses, bids, outcomes
rows=[]
for g in games:
    o=g['outcome']; lic=o.get('license') or {}
    # find bid actions in round 4
    bids={}
    for pa in g['phase_actions']:
        if pa['round']==4 and pa['phase']=='action':
            for a in pa['actions']:
                if a['action']=='bid':
                    bids[a['actor']]=a['detail']
    rows.append((g['id'],g['subject_idx'],o['ranks'],o['payouts'],lic.get('bid'),lic.get('holder_idx'),lic.get('rent'),bids))
for r in rows:
    print(r)
print('N license sold', sum(1 for r in rows if r[5] is not None))
rents=[r[6] for r in rows if r[6] is not None]
print('rent min/max/avg', min(rents), max(rents), sum(rents)/len(rents))"}
